<template>
  <main class="evaluations">
    <header><div><p class="eyebrow">AI 助手 · 质量记录</p><h1>评测看板</h1><p>看实际结果，也看回答的代价。</p></div><nav><button @click="setTheme(theme === 'dark' ? 'light' : 'dark')">{{ theme === 'dark' ? '浅色外观' : '深灰外观' }}</button><button :disabled="loading" @click="load">{{ loading ? '读取中' : '刷新结果' }}</button><RouterLink to="/chat/new">返回聊天</RouterLink></nav></header>
    <p v-if="error" role="alert" class="notice">{{ error }}</p>
    <template v-if="data && current">
      <section class="notice"><strong>检查口径</strong><p>{{ data.method }}</p><p>{{ data.daily }} 页面仅展示已有记录，刷新页面不调用模型。</p></section>
      <div class="run-select"><label>查看批次 <select v-model="selected"><option v-for="run in data.runs.slice().reverse()" :key="run.id" :value="run.id">{{ label(run.phase) }} · {{ date(run.date) }} · {{ run.passed }}/{{ run.total }}</option></select></label><small>快速模式 · 版本 {{ current.runtime.slice(0,12) }}<span v-if="current.incomplete"> · 本批未完整完成</span></small></div>
      <section class="metrics" aria-label="本批指标"><article><span>固定检查通过</span><strong>{{ current.passed }}<small> / {{ current.total }}</small></strong><p>{{ current.manualCount }} 项还需人工复核</p></article><article><span>回答请求 / token</span><strong>{{ number(current.costs.modelRequests) }}<small> 次</small></strong><p>{{ number(current.costs.chatTokens) }} token · 已报告 {{ current.costs.reportedRequests }} 次</p></article><article><span>资料嵌入 token</span><strong>{{ number(current.costs.uploadEmbeddingTokens) }}</strong><p>查询 {{ current.costs.queryEmbeddingTokens === null ? '未记录' : number(current.costs.queryEmbeddingTokens) }} token<span v-if="current.costs.queryEmbeddingUsageUnknown"> · {{ current.costs.queryEmbeddingUsageUnknown }} 轮未知</span></p></article><article><span>回答耗时中位数</span><strong>{{ seconds(current.latency.elapsedMs) }}<small> 秒</small></strong><p>首个正文 {{ seconds(current.latency.ttftMs) }} 秒</p></article></section>
      <p class="search-cost">本批联网搜索 {{ current.costs.webSearches }} 次，缓存命中 {{ current.costs.webSearchCacheHits }} 次；不含搜索服务内部请求和网页读取，不推算金额。</p>
      <section v-if="data.comparison" class="comparison"><h2>同一批案例的改进</h2><p v-if="!data.comparison.comparable">来源或条件变化，不能直接比较通过数。</p><p v-else>同一来源、同一档位、同一组案例。{{ data.comparison.changes.length }} 项检查结果发生变化；随机回答仍可能波动。</p><div class="changes"><span v-for="item in data.comparison.changes" :key="item.id">{{ item.id }} <b>{{ item.before ? '通过' : '未通过' }} → {{ item.after ? '通过' : '未通过' }}</b></span></div></section>
      <section><h2>场景结果</h2><div class="filters" role="group" aria-label="筛选场景"><button v-for="name in ['全部', ...current.categories.map(c=>c.name)]" :key="name" :aria-pressed="category === name" @click="category=name">{{ name }}</button></div><div class="category-bars"><div v-for="group in current.categories" :key="group.name"><span>{{ group.name }}</span><meter :value="group.passed" :max="group.total" min="0" :aria-label="group.name"/><b>{{ group.passed }}/{{ group.total }}</b></div></div><div class="case-list"><article v-for="item in visible" :key="item.id"><div class="case-heading"><strong>{{ item.id }}</strong><span :class="{failed:!item.pass}">{{ item.skipped ? '未完成' : item.pass ? '通过' : '未通过' }}</span></div><p>{{ item.criterion }}</p><small>{{ item.category }} · {{ item.modelRequests }} 次回答请求 · {{ number(item.tokens) }} token<span v-if="item.manualReviewRequired"> · 需人工复核</span></small><p v-if="item.issue" class="issue">{{ item.issue }}<span v-if="item.failedChecks.length">（{{ item.failedChecks.join('、') }}）</span></p></article></div></section>
      <section class="sources"><h2>真实来源与复现</h2><p>原件在 D 盘保存，固定哈希用于核对。同一题的不同批次会各自留下记录。</p><article v-for="source in current.sources" :key="source.id"><a :href="source.url" target="_blank" rel="noopener noreferrer">{{ source.id }}</a><small>{{ source.license }}</small><code>{{ source.sha256 }}</code></article><p class="record">本地原始记录：{{ current.record }}</p></section>
      <footer>累计 {{ data.totals.runs }} 批 · {{ number(data.totals.modelRequests) }} 次回答请求 · {{ number(data.totals.chatTokens) }} 回答 token · {{ number(data.totals.uploadEmbeddingTokens) }} 上传嵌入 token · {{ number(data.totals.knownQueryEmbeddingTokens) }} 已知查询嵌入 token<span v-if="data.totals.unknownQueryTurns"> · {{ data.totals.unknownQueryTurns }} 轮查询嵌入用量未知</span>。消费记录包含失败批次，不推算金额。</footer>
    </template>
    <p v-else-if="!loading && !error" class="notice">当前部署暂无评测记录。公开源码不附带原始评测数据，可按评测文档建立自己的记录。</p>
  </main>
</template>
<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue'
import {useTheme} from '@/composables/useTheme'
interface Case {id:string;category:string;criterion:string;pass:boolean;manualReviewRequired:boolean;skipped:boolean;failedChecks:string[];modelRequests:number;tokens:number;issue:string|null}
interface Run {id:string;profile:string;phase:string;date:string;runtime:string;passed:number;total:number;manualCount:number;incomplete:boolean;cases:Case[];categories:{name:string;passed:number;total:number}[];costs:{modelRequests:number;reportedRequests:number;chatTokens:number;uploadEmbeddingTokens:number;queryEmbeddingTokens:number|null;queryEmbeddingUsageUnknown:number;webSearches:number;webSearchCacheHits:number};latency:{elapsedMs:number|null;ttftMs:number|null};sources:{id:string;url:string;sha256:string;license:string}[];record:string}
interface Dashboard {method:string;daily:string;runs:Run[];comparison:{comparable:boolean;changes:{id:string;before:boolean;after:boolean}[]}|null;totals:{runs:number;modelRequests:number;chatTokens:number;uploadEmbeddingTokens:number;knownQueryEmbeddingTokens:number;unknownQueryTurns:number}}
const {theme,setTheme}=useTheme(),data=ref<Dashboard>(),selected=ref(''),category=ref('全部'),loading=ref(false),error=ref('')
const current=computed(()=>data.value?.runs.find(r=>r.id===selected.value)),visible=computed(()=>current.value?.cases.filter(c=>category.value==='全部'||c.category===category.value)||[])
const number=(n:number)=>n.toLocaleString('zh-CN'),seconds=(n:number|null)=>n===null?'—':(n/1000).toFixed(2),date=(d:string)=>new Date(d).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}),label=(p:string)=>p.startsWith('daily')?'每日小批次':p.startsWith('holdout')?'新变式':p.startsWith('release')?'部署后复核':({baseline:'修改前',final:'修改后'}[p]||p)
async function load(){loading.value=true;error.value='';try{const r=await fetch('/evaluations/latest.json',{cache:'no-store'});if(r.status===404||(r.ok&&!r.headers.get('content-type')?.includes('application/json'))){data.value=undefined;return}if(!r.ok)throw new Error();const d:Dashboard=await r.json();if(!Array.isArray(d.runs))throw new Error();data.value=d;if(!d.runs.some(r=>r.id===selected.value)){const daily=d.runs.filter(r=>r.profile==='daily');selected.value=daily[daily.length-1]?.id||d.runs[d.runs.length-1]?.id||''}}catch{error.value='评测记录暂时无法读取，请稍后刷新。'}finally{loading.value=false}}
watch(selected,()=>{category.value='全部'});onMounted(load)
</script>
<style scoped>
.evaluations{width:min(1120px,100%);margin:auto;padding:36px 28px 48px;color:var(--text-primary);box-sizing:border-box}header{display:flex;gap:24px;justify-content:space-between;align-items:center;margin-bottom:28px}h1{font-size:30px;margin:6px 0 10px;font-weight:600}h2{font-size:19px;margin:0 0 16px}p{color:var(--text-secondary);line-height:1.65;margin:8px 0}.eyebrow,small{font-size:12px;color:var(--text-secondary)}nav{display:flex;flex-wrap:wrap;gap:8px}button,select,nav a{font:inherit;font-size:13px;border:1px solid var(--border);border-radius:8px;background:var(--bg-card);color:var(--text-primary);padding:9px 12px;cursor:pointer}nav a{text-decoration:none;white-space:nowrap}button:hover,button[aria-pressed=true]{background:var(--bg-selected)}button:disabled{opacity:.6;cursor:wait}button:focus-visible,a:focus-visible,select:focus-visible{outline:2px solid var(--text-primary);outline-offset:3px}.notice,.comparison{padding:18px 20px;background:var(--bg-subtle);border:1px solid var(--border-light);border-radius:12px}.notice p{font-size:13px}.run-select{display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:12px;margin:22px 0}.run-select label{font-size:13px;display:flex;align-items:center;flex-wrap:wrap;gap:10px}.run-select select{max-width:100%}.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-bottom:24px}.metrics article{padding:18px;background:var(--bg-card);border:1px solid var(--border-light);border-radius:12px}.metrics article>span{font-size:12px;color:var(--text-secondary)}.metrics strong{display:block;font-size:29px;font-weight:500;margin:12px 0 8px}.metrics p{font-size:12px}.metrics strong small{font-size:14px}.comparison{margin-bottom:28px}.changes{display:flex;flex-wrap:wrap;gap:8px}.changes span{padding:8px 10px;border:1px solid var(--border);border-radius:7px;font-size:12px;overflow-wrap:anywhere}.changes b{display:block;font-weight:500;margin-top:4px}.filters{display:flex;flex-wrap:wrap;gap:8px;margin:14px 0}.category-bars{display:grid;grid-template-columns:1fr 1fr;gap:10px 28px;margin:20px 0}.category-bars div{display:flex;align-items:center;gap:10px;font-size:12px}.category-bars span{width:84px}.category-bars meter{flex:1;min-width:30px;height:8px;accent-color:var(--text-primary)}.category-bars meter::-webkit-meter-bar{background:var(--bg-selected);border:0}.category-bars meter::-webkit-meter-optimum-value{background:var(--text-secondary)}.category-bars b{font-weight:400;min-width:30px;text-align:right}.case-list{display:grid;grid-template-columns:1fr 1fr;gap:12px}.case-list article{min-width:0;padding:16px;border:1px solid var(--border-light);border-radius:10px;background:var(--bg-card)}.case-heading{display:flex;justify-content:space-between;gap:10px;align-items:start}.case-heading strong{font-family:var(--font-mono);font-size:13px;overflow-wrap:anywhere;font-weight:500}.case-heading span{font-size:12px;border:1px solid var(--border);border-radius:5px;padding:2px 7px;white-space:nowrap}.case-heading .failed{border-style:dashed;background:var(--bg-selected)}.case-list p{font-size:13px}.issue{font-weight:500}.sources{margin-top:32px}.sources article{display:grid;gap:6px;padding:14px 0;border-bottom:1px solid var(--border-light)}.sources a{color:var(--citation);font-size:14px}.sources code{font-size:11px;overflow-wrap:anywhere;color:var(--text-muted)}.sources .record{overflow-wrap:anywhere;font-size:12px}footer{margin-top:30px;font-size:12px;color:var(--text-secondary);line-height:1.8}@media(max-width:760px){.evaluations{padding:22px 16px 36px}header{align-items:start;flex-direction:column;gap:12px}.metrics{grid-template-columns:1fr 1fr}.case-list,.category-bars{grid-template-columns:1fr}.run-select select{width:100%;font-size:12px}.notice,.comparison{padding:14px}.run-select label{width:100%}}@media(max-width:360px){.evaluations{padding-inline:12px}.metrics article{padding:12px}.metrics strong{font-size:25px}nav{gap:6px}nav button,nav a{padding:8px;font-size:12px}}
</style>
